import{_ as t,l as i,o as a,c as s,v as n,p as c,x as r,d as l,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Mooncake Transfer Engine","description":"","frontmatter":{"title":"Mooncake Transfer Engine","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mooncake-transfer-engine.md","filePath":"llm/mooncake-transfer-engine.md","lastUpdated":1789023840000}'),p={name:"llm/mooncake-transfer-engine.md"};function C(M,e,E,h,g,D){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="mooncake-transfer-engine" tabindex="-1">Mooncake Transfer Engine <a class="header-anchor" href="#mooncake-transfer-engine" aria-label="Permalink to &quot;Mooncake Transfer Engine&quot;">​</a></h1><div class="epigraph"><p>预先注册内存，按拓扑挑网卡，批量提交 DRAM↔VRAM 与节点间 RDMA；集合通信库不擅长的动态端点与主机内存路径，由传输引擎当成一等操作。</p><footer>—— Qin et al., Mooncake, FAST 2025 §3.2；Mooncake Transfer Engine 设计文档</footer></div><p><a href="/llm/pd-disaggregation">PD 分离</a> 之后，KV 必须搬家；<a href="/llm/mooncake">Mooncake 池</a> 还要把块在 GPU、主机 DRAM、SSD 与远端节点之间复制。NCCL 面向训练期相对固定的 rank 集合，难以优雅处理工人增减，也不把 DRAM↔DRAM 当主路径。Qin、Li、He、Cui、Ren、Zhang、Wu、Zheng、Xu 的 FAST 2025 文本把 <strong>Transfer Engine</strong> 写成 Store 底下的批量传输层：注册、拓扑感知选路、异步完成查询。开源仓库随后把它拆成可被 vLLM / SGLang 单独链接的组件。本篇只写这一层；对象语义与副本策略见 <a href="/llm/mooncake-store">Mooncake Store</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次有用的 KV 搬运要同时满足：体积按层数×前缀长度线性涨（DistServe 给过 OPT-66B、512 token 约 1.13GB 的例子）；延迟必须叠进 TTFT 而不是另开一张墙钟；源和目的可能是 VRAM、pinned DRAM 或远端 DRAM；端点集合随 prefill/decode 工人扩缩而变。用 TCP 搬 GB 级张量，墙钟往往高过重算。用 NCCL 做点对点，动态拓扑与主机内存路径别扭。还要避开跨 NUMA / 跨 PCIe 开关的绕路：从「任意网卡都能发」到「这张卡走这张 NIC」差的是一整条 UPI 或 PCIe 的有效带宽。</p><p>Mooncake 的复用不等式把问题定量化：LLaMA3-70B、前缀 8192，8×A800 上加载带宽大约要 6GB/s 量级才比重算划算，8×H800 上大约 19GB/s——更快的 GPU 让重算变便宜，对传输更苛刻。Transfer Engine 必须把有效带宽做到这个数量级，而不是报网卡标称峰值。</p><h3 id="为何预注册" tabindex="-1">为何预注册 <a class="header-anchor" href="#为何预注册" aria-label="Permalink to &quot;为何预注册&quot;">​</a></h3><p>RDMA 与 GPU Direct 要求内存被 pin、被网卡登记。若每次 <code>get</code> 临时注册，延迟和失败模式都不可控。引擎的契约是：调用方（Store 或 PD connector）在分配分页块或主机缓冲时就注册，传输只提交已登记区间的列表。生命周期必须与 CUDA 分配器、分页回收对齐，否则会出现「页已还、网卡仍以为可写」的远程故障。</p><p><span class="marginnote">GPU Direct RDMA 还要求 NIC 与 GPU 处于合适的 PCIe 拓扑（常见讨论里的 PIX）。经 PXB/NODE 绕行时，BAR1 带宽可能让「直接读 GPU」慢过「先拷到 pinned DRAM 再 RDMA」。引擎按拓扑选路径，不是永远 Direct。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上层看到的是同步批量传输加异步状态：对已注册的 DRAM 或 VRAM 区间做 <code>put</code>/<code>get</code> 一类批量操作，用 <code>getTransferStatus</code> 查询进行中或出错。能走 GPU Direct 则绕过主机 bounce buffer。设计文档列出的后端包括：本机 memcpy / <code>cudaMemcpy</code>（目的其实在本地时）、TCP（DRAM↔远端 DRAM）、RDMA（多网卡池化与重试）、NVLink、HIP（AMD 上的 IPC/可共享句柄）、cuFile / GPUDirect Storage（NVMe-oF）、以及 EFA 等。失败时在优选 NIC 与备选 NIC 之间改道，而不是把整次请求打成失败给上层重算——上层仍可选择重算，但那是策略，不是传输层默认。</p><p>拓扑：每个节点生成矩阵，按内存类型（注册时声明）把 NIC 分成 preferred 与 secondary。正常情况只从 preferred 里选，使 RDMA 留在本 NUMA 或本 PCIe 开关内；失败才动 secondary。传输时根据源/目的地址解析两端 NIC、建连接、提交。环境变量如 <code>MC_IB_SL</code> 可把 KV 流量划到与专家并行 All-to-All 不同的虚拟通道，避免同 NIC 上两类流量互相排队。</p><p>仓库给出的带宽数字：约 40GB 数据（对应他们文中 LLaMA3-70B 约 128k token 量级的 KV）上，Transfer Engine 在 4×400 Gbps RoCE 约 88GB/s、8×400 Gbps 约 190GB/s，相对 TCP 约 2.4× 与 4.6×。这是传输微基准，不是端到端 tokens/s。vLLM 从 2024-12 起官方支持用 Mooncake Transfer Engine 做分离式前填的 KV 搬运；SGLang 后续也把它用于大规模 RL 的权重 RDMA 同步——同一数据面，另一种载荷。</p>',13)),(a(),c(A,null,{default:r(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%B3%A8%E5%86%8C%20DRAM%20%2F%20VRAM%20%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20API%5B%22%E6%89%B9%E9%87%8F%20transfer%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20API%20--%3E%20TOPO%5B%22%E6%8B%93%E6%89%91%E7%9F%A9%E9%98%B5%EF%BC%9Apreferred%20%2F%20secondary%20NIC%22%5D%0A%20%20TOPO%20--%3E%20LOC%7B%22%E7%9B%AE%E7%9A%84%E6%98%AF%E5%90%A6%E6%9C%AC%E6%9C%BA%22%7D%0A%20%20LOC%20--%3E%7C%E6%98%AF%7C%20CPY%5B%22memcpy%20%2F%20cudaMemcpy%20%2F%20NVLink%22%5D%0A%20%20LOC%20--%3E%7C%E5%90%A6%7C%20RDMA%5B%22RDMA%20%2F%20GPU%20Direct%22%5D%0A%20%20RDMA%20--%3E%20RETRY%5B%22%E5%A4%B1%E8%B4%A5%E6%8D%A2%20NIC%20%E9%87%8D%E8%AF%95%22%5D%0A%20%20CPY%20--%3E%20ST%5B%22getTransferStatus%22%5D%0A%20%20RETRY%20--%3E%20ST%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h3 id="和-nccl、nixl-的边界" tabindex="-1">和 NCCL、NIXL 的边界 <a class="header-anchor" href="#和-nccl、nixl-的边界" aria-label="Permalink to &quot;和 NCCL、NIXL 的边界&quot;">​</a></h3><p>NCCL 优化的是固定 communicator 上的集合与 P2P，训练拓扑变化慢。Transfer Engine 优化的是推理期<strong>动态点对点</strong>与<strong>主机内存参与</strong>的 KV/对象搬运。Dynamo 的 <a href="/llm/nvidia-dynamo">NIXL</a> 目标同类：统一 HBM/DRAM/存储的非阻塞 API，后端走 UCX、GDS。生产集群应选一条数据面贯穿 P→D 与分层卸载，避免同一块内存向两套库注册。Mooncake 论文明确写：NCCL 不能妥善处理节点/NIC 动态增减，也不支持 DRAM-to-DRAM 主路径；这是他们自研引擎的动机，不是对 NCCL 训练用途的否定。</p><p>vLLM Omni 连接器文档给出对照：CPU pinned 池（GPU→主机池→RDMA→主机池→GPU）对多数拓扑更稳；GPUDirect 池要求 PIX。一份内部对照里，Mooncake Store 走 TCP 的墙钟约 810ms，Transfer Engine CPU 路径约 14ms、约 22GB/s，加速约 58×——这说明 <strong>Store 的对象路径若降级到 TCP，会把 Engine 的带宽优势吃光</strong>。分层时热路径必须钉在 Engine 的 RDMA 上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效带宽来自三条：零拷贝（注册内存上 NIC 直接读）、多 NIC 聚合（块打散到多卡发送）、拓扑局部性（不穿过 UPI）。副本策略在 Store 层用 <code>change_replica</code> 把热点系统提示摊到多节点，传输层负责把「多副本」变成「多源聚合带宽」。没有 Engine，多副本只是多份慢拷贝；没有副本，单 NIC 先成为 TTFT 墙。</p><p>异步状态让前填工人在传输未完成时继续接下一条，解码工人在 KV 未齐时不开始注意力。这与 DistServe 的 pull 缓冲同一思想，只是实现从 NCCL 换成注册内存上的批量 RDMA。重试换 NIC 是为了尾延迟：推理 SLO 对单次超时比训练更敏感，宁可次优路径送达，不要卡在一条拥塞的 QP 上。</p><p><span class="marginnote">注册表是进程内状态。fork、CUDA context 重建、worker 崩溃重启都必须重新注册。漏注册的症状是偶发 RDMA 失败，而不是 Python 异常栈，排障要看引擎日志与 <code>ibv</code> 计数。</span></p><h3 id="载荷不限于-kv" tabindex="-1">载荷不限于 KV <a class="header-anchor" href="#载荷不限于-kv" aria-label="Permalink to &quot;载荷不限于 KV&quot;">​</a></h3><p>同一套注册与选路可以搬权重（RL 同步）、激活、甚至请求附件。语义由上层定义。把 Engine 写成「只能搬 KV」会低估它，也会在权重量级传输时误用 KV 的 QoS 队列。<code>MC_IB_SL</code> 存在，就是为了让不同载荷走不同虚拟通道。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>标称 400 Gbps × 8 不等于 190GB/s 对每条小消息都成立。Engine 的数字来自大块、批量提交；按 token 逐步搬会把带宽变成延迟。PD 路径应按层或按大块刷，与 <a href="/llm/pd-kv-transfer">KV 传输</a> 的分层重叠一致。TCP 后端是功能降级，不能拿来验证「复用比重算便宜」的不等式。</p><p>与分页块大小的耦合：块太小，每次传输的 WQE 过多；块太大，内部碎片与调度粒度变差。Engine 不管块语义，只看见区间列表——把碎片拼成大 scatter-gather 是 Store 或 connector 的责任。GPU 分配器若频繁申请释放，注册抖动会比搬运本身更贵；实践上对 KV 池做一次大注册，再在池内划块。</p><p>不要把 FAST 论文的集群收益（请求容量 +59%–498%、生产相对旧系统 +115%/+107%）算成 Transfer Engine 微基准的功劳。那些数字是 Store + Conductor + PD 分离 + 调度的总和。Engine 的功劳是让不等式左边的 \\(B\\) 足够大。</p><p><span class="marginnote">出处钉 Qin et al., <em>Mooncake: Trading More Storage for Less Computation</em>, FAST 2025（arXiv:2407.00079）§3.2；设计文档 <a href="https://kvcache-ai.github.io/Mooncake/design/transfer-engine/%EF%BC%9B%E4%BB%A3%E7%A0%81" target="_blank" rel="noreferrer">https://kvcache-ai.github.io/Mooncake/design/transfer-engine/；代码</a> <a href="https://github.com/kvcache-ai/Mooncake%E3%80%82vLLM" target="_blank" rel="noreferrer">https://github.com/kvcache-ai/Mooncake。vLLM</a> 分离式前填支持见项目 2024-12 发行说明。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Transfer Engine 是注册内存上的批量、拓扑感知、可重试 RDMA/本地拷贝层，服务 KV 与其它近 GPU 载荷。</li><li>相对 NCCL，它把动态端点与 DRAM 路径当主场景；相对 TCP，大块带宽高数倍。</li><li>预注册与 PCIe/NUMA 局部性决定 Direct 是否划算；拓扑不对时 pinned DRAM 中转更快。</li><li>它提供带宽 \\(B\\)，不提供对象语义；副本与淘汰在 Store。</li><li>端到端容量数字属于整套 Mooncake，不能单独记在 Engine 上。</li><li>出处：Qin et al., FAST 2025；Mooncake Transfer Engine 文档与仓库。</li></ul>',16))])}const m=t(p,[["render",C]]);export{f as __pageData,m as default};
